"""AI-written decision artifacts, generated by the scripted fake model."""

from __future__ import annotations

from conftest import RUN_BODY, wait_for_run

from backend.assistant.artifacts import priority

LLM = {"llm": {"provider": "anthropic", "model": "fake-model", "api_key": "sk-test"}}


def _run(client) -> str:
    return wait_for_run(client, client.post("/api/runs", json=RUN_BODY).json()["id"])["id"]


def test_priority_buckets():
    assert priority("high", "high", "low") == (9.0, "now")
    assert priority("high", "medium", "medium") == (3.0, "next")
    assert priority("low", "medium", "high") == (0.67, "later")


def test_decisions_are_ranked_validated_and_keep_status(client):
    run_id = _run(client)
    assert client.get(f"/api/runs/{run_id}/artifacts/decisions").json() == {"artifact": None}
    content = client.post(f"/api/runs/{run_id}/artifacts/decisions", json=LLM).json()["artifact"]["content"]
    first, second = content["decisions"]
    assert first["title"] == "Make login reliable" and first["priority"] == "now"  # ranked by score, not model order
    assert second["priority"] == "later"
    assert first["review_ids"] and "made-up-id" not in first["review_ids"]  # invented citations removed
    assert set(content["reviews"]) == set(first["review_ids"])

    updated = client.patch(f"/api/runs/{run_id}/artifacts/decisions/{first['id']}", json={"status": "planned"})
    assert updated.json()["artifact"]["content"]["decisions"][0]["status"] == "planned"
    assert (
        client.patch(f"/api/runs/{run_id}/artifacts/decisions/{first['id']}", json={"status": "meh"}).status_code == 400
    )
    # Regenerating keeps statuses for the same theme and lens.
    again = client.post(f"/api/runs/{run_id}/artifacts/decisions", json=LLM).json()["artifact"]["content"]
    assert again["decisions"][0]["status"] == "planned"


def test_report_with_method_fallback_evidence_and_markdown(client):
    run_id = _run(client)
    report = client.post(f"/api/runs/{run_id}/artifacts/report", json=LLM).json()["artifact"]["content"]
    assert report["method"].startswith("60 Google Play reviews of Example App")
    assert report["key_findings"][0]["review_ids"] and "made-up-id" not in report["key_findings"][0]["review_ids"]
    # The model forgot to cite the second finding; evidence is matched from review themes in its text.
    assert report["key_findings"][1]["review_ids"]
    assert report["recommendations"][0]["when"] == "next"  # invalid value normalised
    md = client.get(f"/api/runs/{run_id}/artifacts/report/markdown")
    assert md.headers["content-disposition"].startswith("attachment")
    assert md.text.startswith("# Login is the problem") and "## Method" in md.text and "> “" in md.text


def test_what_changed_and_personas(client):
    run_id = _run(client)
    changed = client.post(f"/api/runs/{run_id}/artifacts/what_changed", json=LLM).json()["artifact"]["content"]
    assert changed["compared"] and changed["changes"][0]["kind"] == "worse"
    personas = client.post(f"/api/runs/{run_id}/artifacts/personas", json=LLM).json()["artifact"]["content"]
    assert personas["personas"][0]["name"] == "The veteran" and personas["reviews"]
    assert client.get(f"/api/runs/{run_id}/artifacts/nonsense").status_code == 404


def test_inline_review_ids_become_citations():
    from backend.assistant.artifacts import _clean_points

    citable = {"abc-123": {"themes": []}}
    points = _clean_points(
        [{"heading": "Login", "detail": "It fails. Review IDs: ['abc-123', 'made-up']", "review_ids": []}], citable
    )
    assert points == [{"heading": "Login", "detail": "It fails.", "review_ids": ["abc-123"]}]


def test_change_labels_come_from_the_numbers():
    from backend.assistant.artifacts import change_kind

    assert change_kind(0, 3, 0.0, 0.05, praise=False) == "new"
    assert change_kind(2, 9, 0.02, 0.09, praise=False) == "worse"  # a problem mentioned more often
    assert change_kind(5, 3, 0.05, 0.03, praise=False) == "better"  # a problem mentioned less
    assert change_kind(5, 9, 0.05, 0.09, praise=True) == "better"  # praise mentioned more
    assert change_kind(4, 4, 0.040, 0.045, praise=False) == "steady"
